import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"分布式","description":"","frontmatter":{},"headers":[],"relativePath":"architect/distributed/basic/index.md","filePath":"architect/distributed/basic/index.md"}`),a={name:`architect/distributed/basic/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="分布式" tabindex="-1">分布式 <a class="header-anchor" href="#分布式" aria-label="Permalink to “分布式”">​</a></h1><ul><li>是指由多个地理上分散、通过网络连接的独立计算机（节点） 组成，这些节点遵循统一的协议或规则，协同完成一个或多个共同目标（如数据存储、计算任务、服务提供）的系统。</li></ul><h2 id="对比单机" tabindex="-1">对比单机 <a class="header-anchor" href="#对比单机" aria-label="Permalink to “对比单机”">​</a></h2><table tabindex="0"><thead><tr><th>对比维度</th><th>单机</th><th>分布式</th></tr></thead><tbody><tr><td>硬件组成</td><td>单台计算机（CPU、内存、存储集成）</td><td>多台独立计算机（节点）+ 网络</td></tr><tr><td>算力 / 存储上限</td><td>受单台设备硬件限制（如 CPU 核心数、硬盘容量）</td><td>可通过 “增加节点” 线性扩展（理论无上限）</td></tr><tr><td>可用性</td><td>单机故障则整个系统不可用（单点风险）</td><td>部分节点故障不影响整体，可用性更高</td></tr><tr><td>复杂度</td><td>低（无需处理节点通信、数据同步）</td><td>高（需解决网络延迟、数据一致性等问题）</td></tr><tr><td>适用场景</td><td>小型应用、个人工具（如本地 Office）</td><td>大型互联网应用、大数据处理（如电商、短视频）</td></tr></tbody></table>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};